script:
const api = visibExt.api('demo_v2_customizer');

// 1. Регистрируем тему Neon Cyber
api.themes.register({
  id: 'theme_neon_cyber',
  name: 'Neon Cyberpunk 🌌',
  cssVars: {
    '--bg-primary': '#0a0a12',
    '--bg-secondary': '#121220',
    '--accent': '#00f0ff',
    '--border': 'rgba(0, 240, 255, 0.25)',
    '--text-primary': '#ffffff'
  }
});

// 2. Добавляем свою опцию в Настройки -> Основные с бэйджиком
api.settings.addControl('main', {
  id: 'ext_cyber_glow',
  groupTitle: 'Персонализация от Ultra Customizer',
  label: 'Анимированное неоновое свечение',
  desc: 'Добавляет неоновый градиент на панель навигации',
  type: 'toggle',
  value: true,
  onChange: (val) => {
    if (val) {
      api.ui.injectCSS('#navbar { box-shadow: 0 0 15px rgba(0,240,255,0.4) !important; }');
      api.notifications.success('Неоновое свечение включено');
    } else {
      api.notifications.info('Свечение отключено');
    }
  }
});

// 3. Добавляем виджет на главную страницу
api.ui.addNTPWidget('<div style="text-align:center; padding: 12px; background: rgba(0,240,255,0.05); border: 1px dashed rgba(0,240,255,0.3); border-radius: 12px; margin-bottom: 20px;">✨ <b>VISIB Extensions V2 Активен</b> — Браузер полностью кастомизирован!</div>');

api.addButton('🌌', 'Neon Theme', () => api.themes.apply('theme_neon_cyber'));
